'use strict';
const PLUS=window.StudyPlusCore;
let cardSearch='',taskSort='priority',toolFilter='',recallSession=null,examSession=null,tfSession=null,exerciseDraft=null;
let focusState={phase:'focus',cycles:0,running:false,end:0,remaining:1500,started:0,duration:1500,saving:false},stopwatch={running:false,start:0,elapsed:0},audioState=null,breathInterval=null;
const extraList=kind=>(state?.extras||[]).filter(e=>e.kind===kind),payloads=kind=>extraList(kind).map(e=>({...e.payload,id:e.id}));
const pref=()=>({...{theme:'light',large:false,reduced:false,focus:25,short:5,long:20,goal:150},...(extraList('settings').at(-1)?.payload||{})});
const pb=(label,action,cls='',attrs='')=>`<button class="${cls}" data-plus="${action}" ${attrs}>${label}</button>`;
const plusForm=(name,body,label='Save')=>`<form class="form" data-plus-form="${name}">${body}<p class="error" role="alert"></p><button type="submit" class="primary">${label}</button></form>`;
const textarea=(label,name,value='',extra='')=>`<label>${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const optionalCourse=value=>`<label>Course (optional)<select name="course_id"><option value="">Personal / all courses</option>${courseOptions(value)}</select></label>`;
const selectField=(label,name,options,value)=>`<label>${label}<select name="${name}" aria-label="${esc(label)}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const setSelect=()=>selectField('Study set','deck_id',state.decks.map(d=>[d.id,d.title]),state.decks[0]?.id);
const plusId=el=>`data-id="${esc(el.id)}"`;
const daysUntil=d=>Math.round((Date.parse(d)-Date.parse(dateNow()))/86400000);
const datePlus=(d,n)=>window.StudyCore.dayAdd(d,n);
const clockText=seconds=>`${Math.floor(Math.max(0,seconds)/60).toString().padStart(2,'0')}:${Math.floor(Math.max(0,seconds)%60).toString().padStart(2,'0')}`;
const weekStart=()=>{const d=new Date(dateNow()+'T12:00:00');return datePlus(dateNow(),-((d.getDay()+6)%7));};
async function toolSave(kind,payload,id){const r=await api('tools',{kind,payload,...(id?{id}:{})});await refresh();return r;}
function applyPreferences(){const p=pref();document.documentElement.dataset.theme=p.theme;document.documentElement.classList.toggle('large-text',p.large);document.documentElement.classList.toggle('reduced-motion',p.reduced);}
function guestBanner(){if(!state?.guest)return '';return `<div class="guest-banner"><div><strong>Guest workspace</strong><span>Saved ${state.memoryOnly?'only in memory for this visit':'in this browser only'}. Export a backup to keep a copy.</span></div><div class="actions">${pb('Back up','backup','small')}${pb('Sign in','sign-in','primary small')}${pb('Leave guest','guest-leave','ghost small')}</div></div>`;}
function toolCard(title,description,action,attrs=''){return `<article class="card"><h2>${title}</h2><p class="muted">${description}</p>${pb('Open →',action,'small',attrs)}</article>`;}
function plusEmptyCourses(){return state.courses.length?'':`<p class="help">Add courses in Courses to link these tools to a class. Personal tools work immediately.</p>`;}
const plusPages={'Toolkit':toolkit,'Focus':focusPage,'Active recall':recallPage,'Card lab':cardLab,'Grade lab':gradeLab,'Progress':progressPage,"What's new":whatsNew};
function whatsNew(){return heading('50 more ways to make progress.','All additions are available to guests and signed-in students. No paid AI service is required.')+`<div class="feature-catalogue">${PLUS.FEATURES.map(f=>`<article class="card"><span class="badge">${f.number} · ${f.section}</span><h3 class="spaced-title">${esc(f.title)}</h3><p class="help">${esc(f.description)}</p>${button('Go to '+f.section+' →','navigate','link',`data-page="${f.section}"`)}</article>`).join('')}</div>`;}
function toolkit(){const tasks=payloads('task').filter(t=>!t.done),sorters={priority:(a,b)=>a.priority-b.priority,due:(a,b)=>(a.due||'9999').localeCompare(b.due||'9999'),estimate:(a,b)=>a.estimate-b.estimate};tasks.sort(sorters[taskSort]);const top=tasks.filter(t=>t.top&&t.top_date===dateNow());const blocks=payloads('block').sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));const deadlines=state.items.filter(i=>i.due&&!i.done).sort((a,b)=>a.due.localeCompare(b.due));return heading('Make room for what matters.','Tasks, priorities, time blocks, and a practical view of the week.',pb('+ Task','edit-tool','primary','data-kind="task"')+pb('+ Time block','edit-tool','','data-kind="block"'))+`<div class="grid two"><section class="card"><div class="card-header"><h2>Today’s top three</h2><span class="badge">${top.length}/3</span></div>${top.map(taskRow).join('')||empty('Choose your priorities','Pin up to three tasks from the inbox below.')}<div class="section-title"><h2>Task inbox</h2><select id="task-sort" aria-label="Sort tasks"><option value="priority" ${taskSort==='priority'?'selected':''}>By priority</option><option value="due" ${taskSort==='due'?'selected':''}>By due date</option><option value="estimate" ${taskSort==='estimate'?'selected':''}>By time estimate</option></select></div>${tasks.map(taskRow).join('')||empty('A clear inbox','Capture the next small thing you need to do.')}<details><summary class="help">Completed tasks (${payloads('task').filter(t=>t.done).length})</summary>${payloads('task').filter(t=>t.done).map(t=>`<div class="row"><span>${esc(t.title)}</span>${pb('Reopen','task-reopen','small',plusId(t))}</div>`).join('')}</details></section><section class="stack"><div class="card"><h2>Deadline countdowns</h2>${deadlines.map(i=>`<div class="row"><div class="row-main"><strong>${esc(i.title)}</strong><p>${esc(courseName(i.course_id))} · ${fmt(i.due)}</p></div><span class="badge ${daysUntil(i.due)<0?'orange':''}">${daysUntil(i.due)===0?'Today':daysUntil(i.due)<0?`${-daysUntil(i.due)}d overdue`:`${daysUntil(i.due)}d left`}</span></div>`).join('')||'<p class="help">Add assignment due dates to see countdowns.</p>'}</div><div class="card"><h2>Workload budget</h2><p class="help">Your open tasks total <strong>${tasks.reduce((n,t)=>n+t.estimate,0)} minutes</strong>. Estimates come from your task entries.</p>${plusForm('budget',field('Available study hours','hours',5,'number','min="0" max="168" step="0.25" required'),'Compare')}<div id="budget-result" role="status"></div></div></section></div><div class="section-title"><h2>Your next seven days</h2>${pb('Export calendar','calendar','small')}</div><div class="week-grid">${Array.from({length:7},(_,n)=>{const day=datePlus(dateNow(),n),daily=blocks.filter(b=>b.date===day),work=deadlines.filter(i=>i.due===day);return `<article class="card day-card"><h3>${fmt(day)}</h3>${daily.map(b=>`<div class="agenda-entry"><span class="badge">${b.start} · ${b.minutes}m</span><strong>${esc(b.title)}</strong><div>${pb('Edit','edit-tool','link',`data-kind="block" ${plusId(b)}`)}</div></div>`).join('')}${work.map(i=>`<div class="agenda-entry"><span class="badge orange">Due</span><strong>${esc(i.title)}</strong></div>`).join('')}${!daily.length&&!work.length?'<p class="help">Open space</p>':''}</article>`;}).join('')}</div>`;}
function taskRow(t){return `<div class="task-row"><div class="row"><input type="checkbox" class="check" data-plus-change="task-complete" data-id="${t.id}" aria-label="Complete ${esc(t.title)}"><div class="row-main"><strong>${esc(t.title)}</strong><p>${['','High','Medium','Low'][t.priority]} priority · ${t.estimate}m${t.due?' · '+fmt(t.due):''}${t.repeat!=='none'?' · repeats '+t.repeat:''}</p></div><div class="actions">${pb(t.top&&t.top_date===dateNow()?'★':'☆','task-pin','ghost small',`${plusId(t)} aria-label="Pin ${esc(t.title)}"`)}${pb('Edit','edit-tool','ghost small',`data-kind="task" ${plusId(t)}`)}</div></div>${t.subtasks.length?`<div class="subtasks">${t.subtasks.map((s,n)=>`<label><input type="checkbox" data-plus-change="subtask" data-id="${t.id}" data-index="${n}" ${s.done?'checked':''}> ${esc(s.title)}</label>`).join('')}</div>`:''}</div>`;}
function focusPage(){const p=pref(),sessions=payloads('session'),minutes=sessions.filter(s=>s.date>=weekStart()&&s.date<=dateNow()).reduce((n,s)=>n+s.minutes,0);return heading('One thing at a time.','Timers, gentle routines, and a record of your real study time.',pb('Timer & goal settings','preferences',''))+`<div class="grid stats">${stat('This week',Math.round(minutes)+'m','Logged focus time','◷')}${stat('Weekly goal',p.goal+'m',Math.round(minutes/p.goal*100)+'% complete','↗')}${stat('Study streak',PLUS.streak(sessions,dateNow())+'d','Consecutive days with logged time','✧')}${stat('Sessions',sessions.length,'Saved study sessions','◈')}</div><div class="grid two"><section class="card focus-timer"><span class="badge" id="focus-phase">${focusState.phase==='focus'?'Focus':focusState.phase==='long'?'Long break':'Short break'} · Cycle ${focusState.cycles+1}</span><div class="timer-number" id="focus-clock">${clockText(focusState.running?(focusState.end-Date.now())/1000:focusState.remaining)}</div><p class="help">${p.focus}m focus · ${p.short}m short break · ${p.long}m long break after four focus intervals. Completed focus time is saved automatically.</p><div class="flash-controls">${pb(focusState.running?'Pause':'Start','focus-toggle','primary')}${pb('Reset','focus-reset','')}${pb('Finish & log','focus-finish','')}</div><p id="focus-notice" class="help" role="status"></p></section><section class="stack"><article class="card"><h2>Open-ended stopwatch</h2><div class="number" id="stopwatch-clock">${clockText((stopwatch.elapsed+(stopwatch.running?Date.now()-stopwatch.start:0))/1000)}</div><div class="actions">${pb(stopwatch.running?'Pause':'Start','stopwatch-toggle','primary small')}${pb('Save session','stopwatch-save','small')}${pb('Reset','stopwatch-reset','ghost small')}</div></article><article class="card"><h2>Settle into the session</h2><p class="help">Sound is generated on your device. Nothing is recorded.</p><div class="actions">${pb(audioState?'Stop background sound':'Play gentle noise','audio','small')}${pb('Breathing pacer','breathing','small')}</div></article></section></div><div class="grid two spaced-grid"><section class="card"><div class="card-header"><h2>Distraction parking lot</h2>${pb('+ Capture','edit-tool','small','data-kind="distraction"')}</div>${payloads('distraction').filter(x=>!x.done).map(x=>`<div class="row"><p class="row-main">${esc(x.text)}</p>${pb('Clear','toggle-distraction','small',plusId(x))}</div>`).join('')||'<p class="help">Park the thought here and come back to your session.</p>'}</section><section class="card"><div class="card-header"><h2>Reflection journal</h2>${pb('+ Reflection','edit-tool','small','data-kind="reflection"')}</div>${payloads('reflection').slice().reverse().slice(0,5).map(r=>`<div class="row"><div><strong>${esc(r.title)}</strong><p class="help">${fmt(r.date)} · ${esc(r.text)}</p>${pb('Edit','edit-tool','link',`data-kind="reflection" ${plusId(r)}`)}</div></div>`).join('')||'<p class="help">What worked today? What will you try next?</p>'}</section></div><div class="section-title"><h2>Session history</h2>${pb('+ Log session','edit-tool','small','data-kind="session"')}</div><div class="card">${sessions.slice().reverse().slice(0,30).map(s=>`<div class="row"><div class="row-main"><strong>${esc(s.title)}</strong><p>${fmt(s.date)} · ${esc(s.method||'Study')}${s.reflection?' · '+esc(s.reflection):''}</p></div><span class="badge">${Math.round(s.minutes*10)/10}m</span>${pb('Edit','edit-tool','ghost small',`data-kind="session" ${plusId(s)}`)}</div>`).join('')||empty('Your next session starts here','Timers save actual elapsed focus time, not the planned duration.')}</div>`;}
function recallPage(){return heading('Recall it. Explain it. Connect it.','Active study tools built around your own material.')+plusEmptyCourses()+`<div class="grid three">${toolCard('Cornell notes','Cues, notes, and a concise summary.','edit-tool','data-kind="cornell"')}${toolCard('Explain it simply','Check an explanation for structure and clarity signals.','exercise','data-mode="feynman"')}${toolCard('Blurting practice','Write from memory, then compare keyword coverage.','exercise','data-mode="blurting"')}${toolCard('Concept glossary','Build definitions and explicit relationships.','glossary')}${toolCard('Concept map','See the links you added between glossary terms.','concept-map')}${toolCard('Mnemonic builder','Turn a list into an acronym and memory sentence.','mnemonic')}${toolCard('Exam revision plan','Distribute topics across days before an exam.','edit-tool','data-kind="exam"')}${toolCard('Written practice exam','Answer a set, reveal the key, and self-assess.','practice-exam')}${toolCard('Topic confidence','Rate confidence and choose what needs attention.','edit-tool','data-kind="confidence"')}</div><div class="grid two spaced-grid"><section class="card"><h2>Your structured notes</h2>${payloads('cornell').slice().reverse().map(n=>`<div class="row"><div class="row-main"><strong>${esc(n.title)}</strong><p>${fmt(n.date)} · ${n.course_id?esc(courseName(n.course_id)):'Personal'}</p></div>${pb('Read','cornell-read','small',plusId(n))}${pb('Edit','edit-tool','ghost small',`data-kind="cornell" ${plusId(n)}`)}</div>`).join('')||'<p class="help">Save a Cornell note to see it here.</p>'}<h2 class="spaced-title">Revision schedules</h2>${payloads('exam').map(x=>`<div class="row"><div class="row-main"><strong>${esc(x.title)}</strong><p>${fmt(x.date)} · ${daysUntil(x.date)} days left</p></div>${pb('Plan','exam-plan','small',plusId(x))}${pb('Edit','edit-tool','ghost small',`data-kind="exam" ${plusId(x)}`)}</div>`).join('')||'<p class="help">Add an exam date and a list of topics.</p>'}</section><section class="card"><h2>Confidence, lowest first</h2>${payloads('confidence').sort((a,b)=>a.rating-b.rating).map(c=>`<div class="row"><div class="row-main"><strong>${esc(c.topic)}</strong><p>${c.course_id?esc(courseName(c.course_id)):'Personal'} · ${fmt(c.date)}</p></div><span class="badge ${c.rating<=2?'orange':'green'}">${c.rating}/5</span>${pb('Update','edit-tool','small',`data-kind="confidence" ${plusId(c)}`)}</div>`).join('')||'<p class="help">A confidence rating is your own reflection, not a predicted grade.</p>'}</section></div><div class="section-title"><h2>Recent recall exercises</h2></div><div class="card">${payloads('exercise').slice().reverse().slice(0,10).map(x=>`<div class="row"><div class="row-main"><strong>${esc(x.title)}</strong><p>${fmt(x.date)} · ${x.mode==='blurting'?'Blurting comparison':'Explanation check'}</p></div>${pb('Read','exercise-read','small',plusId(x))}</div>`).join('')||'<p class="help">Save an explanation or recall comparison to revisit it here.</p>'}</div><div class="section-title"><h2>Mistakes worth revisiting</h2><span class="help">Saved automatically from missed quizzes and typing practice</span></div><div class="card">${payloads('mistake').slice().reverse().map(m=>`<div class="row"><div class="row-main"><strong>${esc(m.question)}</strong><p>Your answer: ${esc(m.given||'Not recorded')} · Key: ${esc(m.answer)}</p><span class="badge ${m.resolved?'green':'orange'}">${m.resolved?'Reviewed':'To revisit'}</span></div>${pb(m.resolved?'Reopen':'Mark reviewed','mistake-toggle','small',plusId(m))}</div>`).join('')||empty('Mistakes are useful feedback','Missed quiz answers will appear here so you can return to them.')}</div>`;}
function cardLab(){const sets=state.decks.filter(d=>(d.title+' '+d.cards.map(c=>c.question+' '+c.answer).join(' ')).toLowerCase().includes(cardSearch.toLowerCase()));return heading('A fresh angle on your flashcards.','Choose how to practice, organize, or print your study sets.',pb('Merge sets','merge','primary'))+`<div class="filters"><input id="card-search" aria-label="Search study sets" placeholder="Search titles, prompts, or answers…" value="${esc(cardSearch)}"></div><div class="grid three">${sets.map(d=>`<article class="card"><span class="badge">${d.cards.length} cards · ${extraList('bookmark').filter(e=>e.payload.deck_id===d.id).length} starred</span><h2 class="spaced-title">${esc(d.title)}</h2><div class="actions">${pb('Reverse','cards','primary small',`data-id="${d.id}" data-mode="reverse"`)}${pb('Type answers','cards','small',`data-id="${d.id}" data-mode="typing"`)}${pb('Shuffle','cards','small',`data-id="${d.id}" data-mode="shuffle"`)}${pb('Starred only','cards','small',`data-id="${d.id}" data-mode="starred"`)}${pb('With hints','cards','small',`data-id="${d.id}" data-mode="hints"`)}${pb('True / false','true-false','small',`data-id="${d.id}"`)}</div><div class="row actions">${pb('Duplicate','duplicate','ghost small',`data-id="${d.id}"`)}${pb('Print sheet','print-sheet','ghost small',`data-id="${d.id}"`)}</div></article>`).join('')||empty('A study set opens the door','Create a set in Study studio, then choose a practice mode here.')}</div>`;}
function gradeLab(){return heading('Know what a score would change.','Calculators use your recorded per-item weights, not a school’s category rules.')+`<div class="grid two"><article class="card"><h2>Grade what-if</h2>${state.courses.length?plusForm('what-if',`${courseSelect()}<div class="split">${field('Hypothetical earned points','score',8,'number','min="0" step="any" required')}${field('Possible points','total',10,'number','min="0.01" step="any" required')}</div>${field('Future item weight','weight',1,'number','min="0.01" max="100" step="any" required')}`,'Calculate'):'<p class="help">Add a course first.</p>'}<div id="what-if-result" role="status"></div></article><article class="card"><h2>Target-grade calculator</h2>${state.courses.length?plusForm('target',`${courseSelect()}${field('Target course percentage','target',90,'number','min="0" max="100" step="any" required')}<div class="split">${field('Future points possible','total',100,'number','min="0.01" step="any" required')}${field('Future item weight','weight',1,'number','min="0.01" max="100" step="any" required')}</div>`,'Find required score'):'<p class="help">Add a course first.</p>'}<div id="target-result" role="status"></div></article></div>${state.courses.map(c=>{const graded=state.items.filter(i=>i.course_id===c.id&&i.score!==null&&i.total).sort((a,b)=>a.date.localeCompare(b.date));return `<div class="section-title"><h2>${esc(c.name)}</h2></div><div class="grid two"><div class="card"><h3>Breakdown by material type</h3>${[...new Set(graded.map(i=>i.kind))].map(kind=>{const a=graded.filter(i=>i.kind===kind),pct=a.reduce((n,i)=>n+i.score/i.total*i.weight,0)/a.reduce((n,i)=>n+i.weight,0)*100;return `<div class="row"><span>${esc(kind)} · ${a.length} items</span><span class="badge">${pct.toFixed(1)}%</span></div>`;}).join('')||'<p class="help">Enter scored work to compare types.</p>'}</div><div class="card"><h3>Recorded score trajectory</h3>${gradeChart(graded)}</div></div>`;}).join('')}`;}
function gradeChart(items){if(!items.length)return '<p class="help">Add dated scores to draw a chart.</p>';const a=items.slice(-30),max=Math.max(100,...a.map(i=>i.score/i.total*100));const points=a.map((i,n)=>[45+(a.length===1?275:n/(a.length-1)*550),175-i.score/i.total*100/max*145]);return `<svg class="grade-chart" viewBox="0 0 640 220" role="img" aria-label="Recorded scores over time"><path d="M45 20V175H610" stroke="#b8b3cc" fill="none"/><text x="5" y="30">${Math.round(max)}%</text><text x="10" y="180">0%</text><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#7b6ed6" stroke-width="3"/>${points.map((p,n)=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#7b6ed6"><title>${esc(a[n].title)}: ${(a[n].score/a[n].total*100).toFixed(1)}% · ${a[n].date}</title></circle>`).join('')}<text x="45" y="205">${fmt(a[0].date)}</text><text x="530" y="205">${fmt(a.at(-1).date)}</text></svg><p class="help">Each point is one recorded score, not a running course average. Most recent 30 shown.</p>`;}
function progressPage(){const sessions=payloads('session'),minutes=sessions.reduce((n,s)=>n+s.minutes,0),reviewed=state.decks.reduce((n,d)=>n+d.reviews.length,0),checks=payloads('checklist'),readings=payloads('reading');const badges=[['First source',state.items.length>=1,'Add one material'],['Card maker',state.decks.length>=1,'Create one study set'],['Practice starter',state.attempts.length>=1,'Finish one game'],['Ten cards revisited',reviewed>=10,'Review ten different cards'],['Two focused hours',minutes>=120,'Log 120 study minutes'],['Seven-day rhythm',PLUS.streak(sessions,dateNow())>=7,'Log study time seven days in a row']];return heading('Notice the progress you’re making.','Checklists, reading, milestones, and workspace care.',pb('Preferences','preferences',''))+`<div class="grid three">${badges.map(([name,earned,why])=>`<article class="card milestone ${earned?'earned':''}"><span class="number">${earned?'✧':'◇'}</span><h3>${name}</h3><p class="help">${why} · ${earned?'Earned':'In progress'}</p></article>`).join('')}</div><div class="grid two spaced-grid"><section class="card"><div class="card-header"><h2>Revision checklists</h2>${pb('+ Checklist','edit-tool','small','data-kind="checklist"')}</div>${checks.map(c=>`<div class="checklist"><h3>${esc(c.title)}</h3>${c.steps.map((s,n)=>`<label><input type="checkbox" data-plus-change="checklist" data-id="${c.id}" data-index="${n}" ${s.done?'checked':''}> ${esc(s.title)}</label>`).join('')}<p class="help">${c.steps.filter(s=>s.done).length}/${c.steps.length} complete</p>${pb('Edit','edit-tool','link',`data-kind="checklist" ${plusId(c)}`)}</div>`).join('')||'<p class="help">Make revision visible, one step at a time.</p>'}</section><section class="card"><div class="card-header"><h2>Reading queue</h2>${pb('+ Reading','edit-tool','small','data-kind="reading"')}</div>${readings.map(r=>`<div class="row"><div class="row-main"><strong>${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a>`:esc(r.title)}</strong><p>${r.current}/${r.pages} pages · ${r.done?'Finished':'In progress'}</p><p>${esc(r.notes)}</p></div>${pb('Update','edit-tool','small',`data-kind="reading" ${plusId(r)}`)}</div>`).join('')||'<p class="help">Keep articles, chapters, and reading progress in one place.</p>'}</section></div><section class="card spaced-grid"><h2>Keep your workspace portable</h2><p class="help">Backups contain your coursework and toolkit data. Restore creates new courses, materials, sets, and tool entries; review schedules and game history start fresh. It adds records without replacing existing work.</p><div class="actions">${pb('Download backup','backup','primary')}${pb('Restore JSON backup','restore','')}${!state.guest&&window.GuestStore.hasData()?pb('Import this browser’s guest work','import-guest',''):''}</div><p class="help">${state.guest?'Guest work is stored on this browser only. Private/incognito windows or clearing site data can remove it.':'Signed-in coursework is saved in your private cloud workspace. Guest data stays separate until you explicitly import it.'}</p></section>`;}
function editTool(kind,ident){const entry=extraList(kind).find(e=>e.id===ident),p=entry?.payload||{},titles={task:'Study task',block:'Study time block',session:'Study session',distraction:'Park a distraction',reflection:'Study reflection',cornell:'Cornell note',glossary:'Glossary term',exam:'Exam revision plan',confidence:'Topic confidence',checklist:'Revision checklist',reading:'Reading queue entry'};let fields='';const title=()=>field('Title','title',p.title||'','text','required maxlength="200"');const day=()=>field('Date','date',p.date||dateNow(),'date','required');switch(kind){
case 'task':fields=title()+`<div class="split">${field('Due date (optional)','due',p.due||'','date')}${selectField('Priority','priority',[[1,'High'],[2,'Medium'],[3,'Low']],p.priority||2)}</div><div class="split">${field('Estimated minutes','estimate',p.estimate||25,'number','min="1" max="1440" required')}${selectField('Repeat when completed','repeat',[['none','Do not repeat'],['day','Every day'],['week','Every week']],p.repeat||'none')}</div>`+textarea('Subtasks (one per line)','subtasks_text',(p.subtasks||[]).map(s=>s.title).join('\n'))+`<label><span><input name="done" type="checkbox" ${p.done?'checked':''}> Completed</span></label>`;break;
case 'block':fields=title()+day()+`<div class="split">${field('Start time (your local time)','start',p.start||'15:00','time','required')}${field('Duration in minutes','minutes',p.minutes||25,'number','min="5" max="1440" required')}</div>`+optionalCourse(p.course_id);break;
case 'session':fields=title()+day()+field('Actual study minutes','minutes',p.minutes||25,'number','min="0.1" max="1440" step="0.1" required')+textarea('Reflection (optional)','reflection',p.reflection||'')+`<input type="hidden" name="method" value="${esc(p.method||'Manual log')}">`;break;
case 'distraction':fields=textarea('What is on your mind?','text',p.text||'','required maxlength="2000"');break;
case 'reflection':fields=title()+day()+textarea('What worked, what was difficult, and what will you do next?','text',p.text||'','required');break;
case 'cornell':fields=title()+optionalCourse(p.course_id)+textarea('Cue questions / key terms','cues',p.cues||'')+textarea('Notes','text',p.text||'','required rows="8"')+textarea('Summary in your own words','summary',p.summary||'');break;
case 'glossary':fields=field('Term','term',p.term||'','text','required')+textarea('Definition','definition',p.definition||'','required')+field('Related terms (comma-separated, matching saved glossary terms)','related',p.related||'')+optionalCourse(p.course_id);break;
case 'exam':fields=title()+field('Exam date','date',p.date||datePlus(dateNow(),7),'date','required')+textarea('Revision topics (one per line)','topics',p.topics||'','required')+field('Minutes per day','minutes',p.minutes||30,'number','min="5" max="480" required')+optionalCourse(p.course_id);break;
case 'confidence':fields=field('Topic','topic',p.topic||'','text','required')+selectField('Your confidence','rating',[[1,'1 — Need to revisit'],[2,'2 — A little unsure'],[3,'3 — Getting there'],[4,'4 — Fairly confident'],[5,'5 — Can explain it']],p.rating||3)+optionalCourse(p.course_id);break;
case 'checklist':fields=title()+textarea('Revision steps (one per line)','steps_text',(p.steps||[]).map(s=>s.title).join('\n'),'required')+optionalCourse(p.course_id);break;
case 'reading':fields=title()+field('Reading link (optional)','url',p.url||'','url')+`<div class="split">${field('Total pages','pages',p.pages||1,'number','min="1" required')}${field('Pages read','current',p.current||0,'number','min="0" required')}</div>`+textarea('Notes','notes',p.notes||'')+optionalCourse(p.course_id)+`<label><span><input name="done" type="checkbox" ${p.done?'checked':''}> Finished</span></label>`;break;
default:throw Error('Unknown editor');}
modal(titles[kind],plusForm('tool',`<input type="hidden" name="kind" value="${kind}"><input type="hidden" name="id" value="${ident||''}">${fields}`)+(ident?`<p>${pb('Delete this entry','tool-delete','danger small',`data-id="${ident}"`)}</p>`:''));}
function preferences(){const p=pref();modal('Make this workspace yours',plusForm('preferences',`${selectField('Theme','theme',[['light','Light'],['dark','Dark']],p.theme)}<label><span><input type="checkbox" name="large" ${p.large?'checked':''}> Larger text</span></label><label><span><input type="checkbox" name="reduced" ${p.reduced?'checked':''}> Reduce animation</span></label><div class="split">${field('Focus interval (minutes)','focus',p.focus,'number','min="1" max="180" required')}${field('Short break (minutes)','short',p.short,'number','min="1" max="60" required')}</div><div class="split">${field('Long break (minutes)','long',p.long,'number','min="1" max="120" required')}${field('Weekly focus goal (minutes)','goal',p.goal,'number','min="1" max="10080" required')}</div><p class="help">Changes apply to the next timer you start. Guest preferences stay in this browser; signed-in preferences follow your account.</p>`));}
function resetFocus(){focusState={phase:'focus',cycles:focusState.cycles,running:false,end:0,remaining:pref().focus*60,started:0,duration:1500,saving:false};}
function stopAllPlus(){resetFocus();stopwatch={running:false,start:0,elapsed:0};if(audioState){audioState.source.stop();audioState.context.close();audioState=null;}}
async function finishFocus(completed=false){const f=focusState;if(f.saving)return;const planned=f.duration||pref()[f.phase==='focus'?'focus':f.phase]*60,remaining=f.running?Math.max(0,(f.end-Date.now())/1000):f.remaining,elapsed=Math.max(0,planned-remaining);if(f.phase==='focus'&&elapsed<6&&!completed)throw Error('Study for at least six seconds before logging a session.');f.saving=true;f.running=false;try{if(f.phase==='focus'){await api('tools',{kind:'session',payload:{title:'Focused study',date:dateNow(),minutes:Math.max(0.1,Math.round(elapsed/6)/10),method:'Pomodoro'}});f.cycles++;f.phase=f.cycles%4===0?'long':'short';}else f.phase='focus';f.remaining=pref()[f.phase==='focus'?'focus':f.phase]*60;f.duration=f.remaining;f.started=0;await refresh();toast(f.phase==='focus'?'Break finished. Ready for another focus interval.':'Focus time saved. Your break is ready.');}finally{f.saving=false;}}
function tickFocus(){if(focusState.running){const left=Math.max(0,(focusState.end-Date.now())/1000);if(!left&&!focusState.saving)finishFocus(true).catch(e=>toast(e.message));const el=$('#focus-clock');if(el)el.textContent=clockText(left);}if(stopwatch.running){const el=$('#stopwatch-clock');if(el)el.textContent=clockText((stopwatch.elapsed+Date.now()-stopwatch.start)/1000);}}
setInterval(tickFocus,500);
async function saveStopwatch(){const elapsed=stopwatch.elapsed+(stopwatch.running?Date.now()-stopwatch.start:0);if(elapsed<6000)throw Error('Track at least six seconds before saving.');await api('tools',{kind:'session',payload:{title:'Open-ended study',date:dateNow(),minutes:Math.round(elapsed/6000)/10,method:'Stopwatch'}});stopwatch={running:false,start:0,elapsed:0};await refresh();toast('Study session saved.');}
async function toggleNoise(){if(audioState){audioState.source.stop();await audioState.context.close();audioState=null;}else{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Audio is unavailable in this browser.');const context=new Audio(),buffer=context.createBuffer(1,context.sampleRate*2,context.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){last=(last+Math.random()*0.04-0.02)/1.02;data[i]=last*2;}const source=context.createBufferSource(),gain=context.createGain();gain.gain.value=0.15;source.buffer=buffer;source.loop=true;source.connect(gain);gain.connect(context.destination);await context.resume();source.start();audioState={context,source};}render();}
function breathing(){modal('Take a steady moment.',`<div class="breathing"><div class="breath-circle"></div><h2 id="breath-phase" aria-live="polite">Breathe in · 4</h2><p class="help">Follow a comfortable pace. Breathe in for four seconds, then out for four. Stop whenever you like.</p></div>`);let second=0;clearInterval(breathInterval);breathInterval=setInterval(()=>{second=(second+1)%8;const el=$('#breath-phase');if(el)el.textContent=(second<4?'Breathe in':'Breathe out')+' · '+(4-second%4);},1000);}
function exercise(mode){exerciseDraft=null;modal(mode==='blurting'?'Write what you remember':'Explain it simply',plusForm('exercise',`<input type="hidden" name="mode" value="${mode}">${field('Topic / title','title','','text','required')}${mode==='blurting'?textarea('Reference material (keep it covered while writing below)','reference','','required'):textarea('Key ideas or a reference (optional)','reference')}${textarea('Your explanation from memory','input','','required rows="7"')}<p class="help">This checks text signals and keyword overlap, not factual correctness or a teacher’s marking rubric.</p>`,'Review my explanation')+'<div id="exercise-result" role="status"></div>');}
function glossary(){modal('Your concept glossary',`<div class="actions">${pb('+ Term','edit-tool','primary small','data-kind="glossary"')}${pb('View concept map','concept-map','small')}</div><label class="form spaced-grid">Search terms<input id="glossary-search" placeholder="Term or definition"></label><div id="glossary-list">${glossaryRows('')}</div>`);}
function glossaryRows(query){return payloads('glossary').filter(g=>(g.term+' '+g.definition).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.term.localeCompare(b.term)).map(g=>`<div class="row"><div class="row-main"><h3>${esc(g.term)}</h3><p>${esc(g.definition)}</p><p class="help">${g.related?'Related: '+esc(g.related):''}</p></div>${pb('Edit','edit-tool','small',`data-kind="glossary" ${plusId(g)}`)}</div>`).join('')||'<p class="help">No matching terms. Add a glossary term to get started.</p>';}
function conceptMap(){const terms=payloads('glossary').slice(0,18),positions=terms.map((_,i)=>({x:115+(i%3)*245,y:45+Math.floor(i/3)*90})),edges=[];terms.forEach((t,i)=>{for(const related of t.related.split(',').map(s=>s.trim().toLowerCase())){const j=terms.findIndex(g=>g.term.toLowerCase()===related);if(j>=0&&j!==i)edges.push([i,j]);}});modal('Connections you’ve made',terms.length?`<svg viewBox="0 0 740 ${Math.max(150,Math.ceil(terms.length/3)*90)}" class="concept-map" role="img" aria-label="Your saved concepts and explicit relationships"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#a89bd2"/></marker></defs>${edges.map(([i,j])=>`<path d="M${positions[i].x} ${positions[i].y}L${positions[j].x} ${positions[j].y}" stroke="#b8acd7" stroke-width="2" marker-end="url(#arrow)"/>`).join('')}${terms.map((t,i)=>`<g><rect x="${positions[i].x-100}" y="${positions[i].y-25}" width="200" height="50" rx="12" fill="#eeebfa" stroke="#c4b9e4"/><text x="${positions[i].x}" y="${positions[i].y+5}" text-anchor="middle" fill="#67548f">${esc(t.term.slice(0,24))}</text><title>${esc(t.term+': '+t.definition)}</title></g>`).join('')}</svg><p class="help">Arrows use the Related terms you entered. Up to 18 terms are shown. Matching term names create links; no relationships are invented.</p>`:empty('Start with two concepts','Add glossary terms and related term names to draw your map.'));}
function mnemonic(){modal('Make a memory cue',plusForm('mnemonic',textarea('Terms to remember (one per line)','terms','','required')+textarea('Optional memory sentence, using the initials in order','sentence'),'Build cue')+'<div id="mnemonic-result" role="status"></div>');}
function showExamPlan(ident){const e=payloads('exam').find(x=>x.id===ident);if(!e)throw Error('Exam not found');const plan=PLUS.revisionPlan(e,dateNow());modal(e.title+' · Revision plan',`<p class="help">${plan.length} study days · ${e.minutes} minutes per day. Topics repeat when there are more days than topics.</p>${plan.map(p=>`<div class="row"><span>${fmt(p.date)}</span><strong>${esc(p.topic)}</strong><span class="badge">${p.minutes}m</span></div>`).join('')}<p>${pb('Add sessions to calendar at 15:00','apply-exam','primary',`data-id="${ident}"`)}</p><p class="help">This adds new time blocks. Repeating it adds another copy; review existing blocks first.</p>`);}
function openPracticeExam(){if(!state.decks.length)throw Error('Create a study set first.');modal('Build a written practice exam',plusForm('exam-start',setSelect()+field('Number of questions','count',10,'number','min="1" max="30" required')+'<p class="help">Questions come from your saved cards. You will self-assess against the answer key.</p>','Begin'));}
function showWrittenExam(){const s=examSession;modal(s.deck.title+' · Written practice',plusForm('exam-submit',s.cards.map((c,n)=>textarea(`${n+1}. ${c.question}`,'answer_'+n,'','required')).join(''),'Reveal answer key'));}
function showExamKey(answers){const s=examSession;s.answers=answers;modal('Review your answers',plusForm('exam-grade',s.cards.map((c,n)=>`<div class="card"><h3>${n+1}. ${esc(c.question)}</h3><p>Your answer: ${esc(answers['answer_'+n])}</p><p><strong>Answer key:</strong> ${esc(c.answer)}</p><label><span><input type="checkbox" name="correct_${n}"> I answered this correctly</span></label></div>`).join('')+'<p class="help">These are self-assessed practice results, not official grades.</p>','Save self-assessment'));}
function bookmark(deckId,index){return extraList('bookmark').find(e=>e.payload.deck_id===deckId&&e.payload.card===index);}
function openCardPractice(d,mode){let cards=d.cards.map((c,index)=>({...c,index}));if(mode==='starred')cards=cards.filter(c=>bookmark(d.id,c.index));if(!cards.length)throw Error('Star some cards first using any Card lab practice mode.');if(mode==='shuffle')cards=shuffle(cards);recallSession={deck:d,cards,index:0,mode,flipped:false,hint:0,checked:false};showPlusCard();}
function showPlusCard(){const s=recallSession,c=s.cards[s.index];if(!c){modal('Practice complete.',`<p class="muted">Your review schedule is saved. Try a game or return tomorrow.</p>${pb('Done','close','primary')}`);return;}const reverse=s.mode==='reverse',question=reverse?c.answer:c.question,answer=reverse?c.question:c.answer;const starred=!!bookmark(s.deck.id,c.index);modal(s.deck.title,`<div class="card-header"><span class="badge">${s.mode} · ${s.index+1}/${s.cards.length}</span>${pb(starred?'★ Starred':'☆ Star card','card-star','small')}</div><h2 class="spaced-title">${esc(question)}</h2>${s.mode==='typing'?plusForm('card-type',field('Type your answer','answer','','text','required'),'Check answer'):`<button class="flashcard" data-plus="card-flip">${s.flipped?esc(answer):'Think of your answer, then reveal it.'}</button>`}<div id="card-feedback" role="status"></div><p class="help">${c.source?'Source: '+esc(c.source):'Your custom card'}</p><div class="actions">${pb('Reveal a hint','card-hint','small')}${s.mode!=='typing'&&s.flipped?pb('Practice again','card-again','')+pb('Got it →','card-known','primary'):''}</div><p id="card-hint" class="help"></p>`);}
async function markPlusCard(known){const s=recallSession,c=s.cards[s.index];await api('review',{deck_id:s.deck.id,card:c.index,known});s.index++;s.flipped=false;s.hint=0;s.checked=false;await refresh();showPlusCard();}
async function saveMistake(deckId,c,given){try{await api('tools',{kind:'mistake',payload:{question:c.question,answer:c.answer,given,deck_id:deckId,card:c.index??0,date:dateNow(),resolved:false}});}catch(e){toast('Practice saved, but the mistake could not be logged: '+e.message);}}
function startTF(d){tfSession={deck:d,cards:shuffle(d.cards.map((c,index)=>({...c,index}))),index:0,correct:0,answered:false};showTF();}
function showTF(){const s=tfSession,c=s.cards[s.index];if(!c)return finishTF();const others=s.deck.cards.map(x=>x.answer).filter(a=>a!==c.answer),truth=!others.length||Math.random()>0.5;s.truth=truth;s.answer=truth?c.answer:others[Math.floor(Math.random()*others.length)];s.answered=false;modal('True or false?',`<p class="help">${s.index+1}/${s.cards.length} · ${s.correct} correct</p><h2>${esc(c.question)}</h2><div class="card"><p>${esc(s.answer)}</p></div><div class="flash-controls">${pb('True','tf-answer','primary','data-value="true"')}${pb('False','tf-answer','','data-value="false"')}</div><div id="tf-feedback" role="status"></div>${s.deck.cards.length===1?'<p class="help">A one-card set always matches. Add different answers for mixed rounds.</p>':''}`);}
async function finishTF(){const s=tfSession;await api('attempt',{deck_id:s.deck.id,correct:s.correct,total:s.cards.length});modal('Round complete.',`<div class="number">${s.correct}/${s.cards.length}</div><p class="muted">Your result and review schedule are saved.</p>${pb('Done','close','primary')}`);await refresh();}
function printSheet(d){modal(d.title+' · Print preview',`<div class="no-print"><p class="help">Choose Print to use your browser’s printer or Save as PDF option.</p>${pb('Print / Save as PDF','print-now','primary')}</div><article class="print-sheet"><h1>${esc(d.title)}</h1>${d.cards.map((c,n)=>`<section><h3>${n+1}. ${esc(c.question)}</h3><p>${esc(c.answer)}</p><p class="help">${esc(c.source||'Custom card')}</p></section>`).join('')}</article>`);}
function mergeForm(){if(state.decks.length<2)throw Error('Create at least two study sets to merge.');modal('Combine your study sets',plusForm('merge',field('New set title','title','Combined study set','text','required')+`<label>Course for the new set<select name="course_id">${courseOptions()}</select></label><fieldset><legend>Choose two or more sets</legend>${state.decks.map(d=>`<label><span><input type="checkbox" name="set_${d.id}"> ${esc(d.title)} · ${d.cards.length} cards</span></label>`).join('')}</fieldset><p class="help">The originals stay unchanged. Duplicate prompt-answer pairs are removed. A merged set can contain up to 200 cards.</p>`,'Create merged set'));}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-plus]');if(!el)return;event.preventDefault();const action=el.dataset.plus,ident=el.dataset.id;el.disabled=true;try{const record=state?.extras?.find(e=>e.id===ident),d=state?.decks.find(d=>d.id===ident);switch(action){
case 'guest-start':stopAllPlus();window.GuestStore.start();page='Overview';await refresh();break;
case 'guest-leave':stopAllPlus();window.GuestStore.leave();state=null;await refresh().catch(()=>auth());break;
case 'sign-in':stopAllPlus();window.GuestStore.leave();location.href='/signin-with-chatgpt?return_to=%2F';break;
case 'backup':download('study-ai-workspace.json',JSON.stringify(state,null,2),'application/json');break;
case 'restore':modal('Restore a workspace backup',plusForm('restore','<label>Study.ai JSON backup<input type="file" name="backup" accept=".json,application/json" required></label><p class="help">Adds new courses, materials, sets, and toolkit entries. It does not replace existing work. Review schedules and game history reset for restored sets.</p>','Import as new records'));break;
case 'import-guest':modal('Import this browser’s guest work?',plusForm('guest-import','<p class="help">Copies guest courses, materials, sets, and toolkit entries into your signed-in account. Your guest copy remains on this device. Importing twice creates duplicates.</p>','Import guest work'));break;
case 'sample':{const c=await api('courses',{name:'Biology · sample course',teacher:'Example teacher',school:'Sample school'});await api('items',{course_id:c.id,title:'Cell biology · sample notes',kind:'note',date:dateNow(),content:'Mitosis: Cell division that produces two genetically identical daughter cells.\nOsmosis: Movement of water across a selectively permeable membrane.\nPhotosynthesis: Plants convert light energy into chemical energy.\nChloroplasts: Organelles where photosynthesis occurs.'});await api('generate',{course_id:c.id,title:'Cell biology · sample set'});await refresh();toast('Sample notes and cards added. All sample data is clearly labeled.');break;}
case 'edit-tool':editTool(el.dataset.kind,ident);break;
case 'tool-delete':modal('Delete this entry?',plusForm('tool-delete',`<input type="hidden" name="id" value="${ident}"><p class="help">This removes the saved entry permanently.</p>`,'Delete permanently'));break;
case 'close':$('#modal').close();break;
case 'task-pin':{if(!record)throw Error('Task not found');const p={...record.payload},on=p.top&&p.top_date===dateNow();if(!on&&payloads('task').filter(t=>!t.done&&t.top&&t.top_date===dateNow()).length>=3)throw Error('Choose up to three priorities for today. Unpin one first.');await toolSave('task',{...p,top:!on,top_date:dateNow()},ident);break;}
case 'task-reopen':await toolSave('task',{...record.payload,done:false},ident);break;
case 'calendar':download('study-ai-calendar.ics',PLUS.calendarICS(state.items,payloads('block')),'text/calendar');break;
case 'preferences':preferences();break;
case 'focus-toggle':if(focusState.running){focusState.remaining=Math.max(0,(focusState.end-Date.now())/1000);focusState.running=false;}else{if(!focusState.started){focusState.duration=focusState.remaining;focusState.started=Date.now();}focusState.end=Date.now()+focusState.remaining*1000;focusState.running=true;}render();break;
case 'focus-reset':resetFocus();render();break;
case 'focus-finish':await finishFocus(false);break;
case 'stopwatch-toggle':if(stopwatch.running){stopwatch.elapsed+=Date.now()-stopwatch.start;stopwatch.running=false;}else{stopwatch.start=Date.now();stopwatch.running=true;}render();break;
case 'stopwatch-reset':stopwatch={running:false,start:0,elapsed:0};render();break;
case 'stopwatch-save':await saveStopwatch();break;
case 'audio':await toggleNoise();break;
case 'breathing':breathing();break;
case 'toggle-distraction':await toolSave('distraction',{...record.payload,done:true},ident);break;
case 'exercise':exercise(el.dataset.mode);break;
case 'exercise-read':{const x=record.payload;modal(x.title,`<p class="help">${fmt(x.date)} · ${x.mode==='blurting'?'Keyword coverage: '+x.score+'%':'Explanation practice'}</p><h3>Your explanation</h3><div class="content">${esc(x.input)}</div>${x.reference?'<h3 class="spaced-title">Reference</h3><div class="content">'+esc(x.reference)+'</div>':''}`);break;}
case 'save-exercise':if(!exerciseDraft)throw Error('Complete an exercise first.');await toolSave('exercise',exerciseDraft);toast('Exercise saved in your workspace backup.');break;
case 'glossary':glossary();break;
case 'concept-map':conceptMap();break;
case 'mnemonic':mnemonic();break;
case 'cornell-read':{const n=record.payload;modal(n.title,`<div class="cornell-grid"><section><h3>Cues</h3><div class="content">${esc(n.cues)}</div></section><section><h3>Notes</h3><div class="content">${esc(n.text)}</div></section><section class="cornell-summary"><h3>Summary</h3><div class="content">${esc(n.summary)}</div></section></div>`);break;}
case 'exam-plan':showExamPlan(ident);break;
case 'apply-exam':{const e=record.payload,plan=PLUS.revisionPlan(e,dateNow());for(const p of plan)await api('tools',{kind:'block',payload:{title:e.title+' · '+p.topic,date:p.date,start:'15:00',minutes:p.minutes,course_id:e.course_id}});$('#modal').close();await refresh();toast('Revision sessions added to your weekly calendar.');break;}
case 'practice-exam':openPracticeExam();break;
case 'mistake-toggle':await toolSave('mistake',{...record.payload,resolved:!record.payload.resolved},ident);break;
case 'cards':openCardPractice(d,el.dataset.mode);break;
case 'card-flip':recallSession.flipped=!recallSession.flipped;showPlusCard();break;
case 'card-star':{const s=recallSession,c=s.cards[s.index],old=bookmark(s.deck.id,c.index);if(old)await api('tools/delete',{id:old.id});else await api('tools',{kind:'bookmark',payload:{deck_id:s.deck.id,card:c.index}});await refresh();showPlusCard();break;}
case 'card-hint':{const s=recallSession,c=s.cards[s.index],answer=s.mode==='reverse'?c.question:c.answer;s.hint++;$('#card-hint').textContent=answer.slice(0,Math.min(answer.length,s.hint*Math.ceil(answer.length/5)))+(s.hint<5?'…':'');break;}
case 'card-known':await markPlusCard(true);break;
case 'card-again':await markPlusCard(false);break;
case 'card-next':recallSession.index++;recallSession.hint=0;recallSession.checked=false;showPlusCard();break;
case 'true-false':startTF(d);break;
case 'tf-answer':{const s=tfSession;if(s.answered)break;s.answered=true;const correct=(el.dataset.value==='true')===s.truth,c=s.cards[s.index];if(correct)s.correct++;document.querySelectorAll('[data-plus="tf-answer"]').forEach(b=>b.disabled=true);$('#tf-feedback').innerHTML=`<p>${correct?'Correct!':'The saved answer is: '+esc(c.answer)}</p>${pb('Next →','tf-next','primary')}`;await api('review',{deck_id:s.deck.id,card:c.index,known:correct});if(!correct)await saveMistake(s.deck.id,c,s.answer);break;}
case 'tf-next':tfSession.index++;showTF();break;
case 'duplicate':await api('decks',{course_id:d.course_id,title:(d.title+' · Copy').slice(0,100),cards:d.cards});await refresh();toast('Editable copy created.');break;
case 'merge':mergeForm();break;
case 'print-sheet':printSheet(d);break;
case 'print-now':document.body.classList.add('printing');window.print();break;
}}catch(error){toast(error.message);}finally{if(action!=='tf-answer')el.disabled=false;}});
document.addEventListener('submit',async event=>{const form=event.target,name=form.dataset.plusForm;if(!name)return;event.preventDefault();const submit=form.querySelector('[type="submit"]');submit.disabled=true;const error=form.querySelector('.error');error.textContent='';const data=Object.fromEntries(new FormData(form));try{switch(name){
case 'tool':{const old=state.extras.find(e=>e.id===data.id),p={...(old?.payload||{}),...data};if(form.elements.done)p.done=form.elements.done.checked;if(data.kind==='task')p.subtasks=data.subtasks_text.split('\n').map(t=>t.trim()).filter(Boolean).map(title=>({title,done:old?.payload.subtasks.find(s=>s.title===title)?.done||false}));if(data.kind==='checklist')p.steps=data.steps_text.split('\n').map(t=>t.trim()).filter(Boolean).map(title=>({title,done:old?.payload.steps.find(s=>s.title===title)?.done||false}));await api('tools',{kind:data.kind,payload:p,...(data.id?{id:data.id}:{})});break;}
case 'tool-delete':await api('tools/delete',{id:data.id});break;
case 'budget':{const available=Number(data.hours)*60,needed=payloads('task').filter(t=>!t.done).reduce((n,t)=>n+t.estimate,0);$('#budget-result').innerHTML=`<p class="spaced-title">${needed<=available?`${Math.round(available-needed)} minutes of breathing room.`:`${Math.round(needed-available)} minutes over budget. Consider reducing scope or moving a task.`}</p>`;return;}
case 'preferences':await api('tools',{kind:'settings',payload:{...data,large:form.elements.large.checked,reduced:form.elements.reduced.checked}});if(!focusState.running&&!focusState.started)focusState.remaining=Number(data.focus)*60;break;
case 'exercise':{const metrics=PLUS.explanationCheck(data.input),match=PLUS.coverage(data.reference,data.input);exerciseDraft={...data,score:match.percent,date:dateNow()};$('#exercise-result').innerHTML=`<div class="card spaced-grid"><h3>${data.mode==='blurting'?'Keyword coverage: '+match.percent+'%':'Explanation signals'}</h3><p>${metrics.words} words · ${metrics.sentences} sentences · ${metrics.long} sentences over 25 words · ${metrics.definitions} definition / example phrases.</p>${data.reference?`<p class="help">Covered: ${esc(match.found.join(', ')||'No matching keywords')}. Revisit: ${esc(match.missing.join(', ')||'No missing keywords')}.</p>`:''}<p class="help">${data.mode==='feynman'?'Try a concrete example, define unfamiliar words, and shorten long sentences.':'Coverage measures matching words, not understanding or correctness. Use the reference to check meaning.'}</p>${pb('Save exercise','save-exercise','primary small')}</div>`;return;}
case 'mnemonic':{const terms=data.terms.split('\n').map(t=>t.trim()).filter(Boolean);if(!terms.length)throw Error('Add at least one term.');const acronym=terms.map(t=>Array.from(t)[0].toUpperCase()).join('');$('#mnemonic-result').innerHTML=`<div class="card spaced-grid"><div class="number">${esc(acronym)}</div><p>${terms.map(t=>esc(t)).join(' → ')}</p><p>${esc(data.sentence||'Write a sentence using these initials, in order: '+acronym.split('').join(' · '))}</p></div>`;return;}
case 'exam-start':{const deck=state.decks.find(d=>d.id===data.deck_id);examSession={deck,cards:shuffle(deck.cards.map((c,index)=>({...c,index}))).slice(0,Math.min(Number(data.count),30))};showWrittenExam();return;}
case 'exam-submit':showExamKey(data);return;
case 'exam-grade':{const s=examSession;let correct=0;for(let i=0;i<s.cards.length;i++){const known=form.elements['correct_'+i].checked;if(known)correct++;await api('review',{deck_id:s.deck.id,card:s.cards[i].index,known});if(!known)await saveMistake(s.deck.id,s.cards[i],s.answers['answer_'+i]);}await api('attempt',{deck_id:s.deck.id,correct,total:s.cards.length});modal('Practice exam saved.',`<div class="number">${correct}/${s.cards.length}</div><p class="muted">Self-assessed results are saved in practice history.</p>${pb('Done','close','primary')}`);await refresh();return;}
case 'card-type':{const s=recallSession;if(s.checked)return;s.checked=true;const c=s.cards[s.index],known=data.answer.trim().toLowerCase()===c.answer.trim().toLowerCase();await api('review',{deck_id:s.deck.id,card:c.index,known});if(!known)await saveMistake(s.deck.id,c,data.answer);$('#card-feedback').innerHTML=`<p>${known?'Matches the saved answer.':'Saved answer: '+esc(c.answer)}</p><p class="help">Typing mode checks exact wording, ignoring case and surrounding spaces.</p>${pb('Next →','card-next','primary')}`;await refresh();return;}
case 'merge':{const selected=state.decks.filter(d=>data['set_'+d.id]);if(selected.length<2)throw Error('Choose at least two sets.');const seen=new Set(),cards=[];for(const d of selected)for(const c of d.cards){const key=c.question+'\u0000'+c.answer;if(!seen.has(key)){seen.add(key);cards.push(c);}}if(cards.length>200)throw Error('The combined set exceeds 200 cards. Choose fewer sets.');await api('decks',{course_id:data.course_id,title:data.title,cards});toast('Merged set created.');break;}
case 'what-if':{const result=PLUS.whatIf(state.items.filter(i=>i.course_id===data.course_id),Number(data.score),Number(data.total),Number(data.weight));$('#what-if-result').innerHTML=`<div class="number">${result}%</div><p class="help">Estimated average after that future item. Your actual records were not changed.</p>`;return;}
case 'target':{const score=PLUS.targetScore(state.items.filter(i=>i.course_id===data.course_id),Number(data.target),Number(data.total),Number(data.weight));$('#target-result').innerHTML=`<div class="number">${Math.max(0,score)} / ${esc(data.total)}</div><p class="help">${score<0?'Your recorded work already supports this target even with a zero on this item.':score>Number(data.total)?'This target needs more than the available points. Change the future weight, add further work, or revise the target.':'Required points on the proposed future item, using your recorded weights.'}</p>`;return;}
case 'restore':{const file=form.elements.backup.files[0];if(!file||file.size>2800000)throw Error('Choose a Study.ai backup under 2.8 MB.');const backup=JSON.parse(await file.text());const result=await api('restore',{backup});toast('Imported '+result.count+' new records.');break;}
case 'guest-import':{const result=await api('restore',{backup:window.GuestStore.backup()});toast('Imported '+result.count+' guest records into your account.');break;}
}$('#modal').close();await refresh();}catch(e){error.textContent=e.message;}finally{submit.disabled=false;}});
document.addEventListener('change',async event=>{const el=event.target,action=el.dataset.plusChange;try{if(el.id==='task-sort'){taskSort=el.value;render();return;}if(!action)return;const record=state.extras.find(e=>e.id===el.dataset.id);if(!record)throw Error('Entry not found');const p=structuredClone(record.payload);if(action==='task-complete'){p.done=el.checked;p.top=false;await api('tools',{id:record.id,kind:'task',payload:p});if(p.done&&p.repeat!=='none')await api('tools',{kind:'task',payload:PLUS.nextRecurring(p,dateNow())});}if(action==='subtask'){p.subtasks[Number(el.dataset.index)].done=el.checked;await api('tools',{id:record.id,kind:'task',payload:p});}if(action==='checklist'){p.steps[Number(el.dataset.index)].done=el.checked;await api('tools',{id:record.id,kind:'checklist',payload:p});}await refresh();}catch(e){toast(e.message);await refresh();}});
let plusSearchTimeout;document.addEventListener('input',event=>{if(event.target.id==='glossary-search')$('#glossary-list').innerHTML=glossaryRows(event.target.value);if(event.target.id==='card-search'){cardSearch=event.target.value;const pos=event.target.selectionStart;clearTimeout(plusSearchTimeout);plusSearchTimeout=setTimeout(()=>{render();const el=$('#card-search');el.focus();el.setSelectionRange(pos,pos);},180);}});
window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
